import type { AutogeneratedInsertableProjectDocument, AutogeneratedProjectDocument } from './autogenerated/autogenerated_project_document.d.ts'

type Expiration = {
	can_expire: true
	expire_days: bigint
} | {
	can_expire: false
	expire_days: null
}

declare global {
	type DbInsertableProjectDocument = Omit<AutogeneratedInsertableProjectDocument, 'can_expire' | 'expire_days'> & Expiration
	type DbProjectDocument = Omit<AutogeneratedProjectDocument, 'can_expire' | 'expire_days'> & Expiration
}
